assert cuotas.ORDEN[0] == "groq", "el primero SIEMPRE es Qwen (Groq)"
assert gratis == ["groq", "gemini4", "gemini2"], \
    "los gratis son groq, gemini4 y gemini2 (A-9/A-31)"
